        { name: 'Grok 4.20 0309 v2', org: 'Other', color: 'var(--teal)', intelligence: 49, speed: 162, price: 3.00 },
        { name: 'Gemini 3 Flash', org: 'Google', color: 'var(--cyan)', intelligence: 46, speed: 149, price: 1.10 },
        { name: 'DeepSeek V3.2', org: 'Other', color: 'var(--teal)', intelligence: 42, speed: 31,  price: 0.30 },
        { name: 'NVIDIA Nemotron 3 Super', org: 'Other', color: 'var(--teal)', intelligence: 36, speed: 193, price: 0.40 },
        { name: 'gpt-oss-120B (high)', org: 'Other', color: 'var(--teal)', intelligence: 33, speed: 206, price: 0.30 },
      ],
      rankings: {
        intelligence: [
          ['Gemini 3.1 Pro Preview', 57],
          ['GPT-5.4 (xhigh)', 57],
          ['Claude Opus 4.6 (max)', 53],
          ['Claude Sonnet 4.6 (max)', 52],
          ['GLM-5.1', 51],
          ['Grok 4.20 0309 v2', 49],
          ['Gemini 3 Flash', 46],
          ['DeepSeek V3.2', 42],
          ['NVIDIA Nemotron 3 Super', 36],
          ['gpt-oss-120B (high)', 33],
        ],
        speed: [
          ['gpt-oss-120B (high)', 206],
          ['NVIDIA Nemotron 3 Super', 193],
          ['Grok 4.20 0309 v2', 162],
          ['Gemini 3 Flash', 149],
          ['Gemini 3.1 Pro Preview', 129],
          ['GPT-5.4 (xhigh)', 72],
          ['Claude Sonnet 4.6 (max)', 48],
          ['GLM-5.1', 40],
          ['Claude Opus 4.6 (max)', 40],
          ['DeepSeek V3.2', 31],
        ],
        price: [
          ['gpt-oss-120B (high)', 0.30],
          ['DeepSeek V3.2', 0.30],
          ['NVIDIA Nemotron 3 Super', 0.40],
          ['Gemini 3 Flash', 1.10],
          ['GLM-5.1', 2.10],
          ['Grok 4.20 0309 v2', 3.00],
          ['Gemini 3.1 Pro Preview', 4.50],
          ['GPT-5.4 (xhigh)', 5.60],
          ['Claude Sonnet 4.6 (max)', 6.00],
          ['Claude Opus 4.6 (max)', 10.00],
        ]
      }
    };

    const chart = document.getElementById('chart');

    const intelMin = 33, intelMax = 57;
    const speedMin = 31, speedMax = 206;
    const priceMin = 0.30, priceMax = 10.00;

    const norm = (v, vmin, vmax) => (v - vmin) / (vmax - vmin);

    const priceToRadius = (p) => {
      const t = Math.max(0, Math.min(1, (p - priceMin) / (priceMax - priceMin)));
      // sqrt scaling -> perceptual area-ish
      return 60 + 210 * Math.sqrt(t); // px
    };

    const abbreviate = (name) => {
      // Keep readable while fitting bubbles
      if (name.startsWith('Gemini 3.1')) return 'Gemini 3.1 Pro';
      if (name.startsWith('Gemini 3 Flash')) return 'Gemini 3 Flash';
      if (name.startsWith('GPT-5.4')) return 'GPT-5.4';
      if (name.startsWith('Claude Opus')) return 'Claude Opus';
      if (name.startsWith('Claude Sonnet')) return 'Claude Sonnet';
      if (name.startsWith('Grok')) return 'Grok 4.20';
      if (name.startsWith('NVIDIA Nemotron')) return 'Nemotron 3';
      if (name.startsWith('gpt-oss')) return 'gpt-oss-120B';
      return name;
    };

    const bubbleOffsets = {
      'Gemini 3.1 Pro Preview': { dx: -36, dy: -12 },
      'GPT-5.4 (xhigh)': { dx: 20, dy: -8 },
      'Claude Opus 4.6 (max)': { dx: -10, dy: 22 },
      'Claude Sonnet 4.6 (max)': { dx: 36, dy: 26 },
      'GLM-5.1': { dx: -26, dy: -22 },
      'Grok 4.20 0309 v2': { dx: 20, dy: -14 },
      'Gemini 3 Flash': { dx: -20, dy: 18 },
      'DeepSeek V3.2': { dx: 40, dy: 10 },
      'NVIDIA Nemotron 3 Super': { dx: -26, dy: 24 },
      'gpt-oss-120B (high)': { dx: -38, dy: -10 },
    };

    const placeBubbles = () => {
      const rect = chart.getBoundingClientRect();
      const w = rect.width;
      const h = rect.height;

      // inset so bubbles don't clip
      const pad = 90;

      for (const m of data.models) {
        const x = pad + (w - 2*pad) * norm(m.speed, speedMin, speedMax);
        const y = pad + (h - 2*pad) * (1 - norm(m.intelligence, intelMin, intelMax));
        const r = priceToRadius(m.price);
        const off = bubbleOffsets[m.name] || { dx: 0, dy: 0 };

        const bubble = document.createElement('div');
        bubble.className = 'bubble';
        bubble.style.left = `${x + off.dx}px`;
        bubble.style.top = `${y + off.dy}px`;
        bubble.style.width = `${r}px`;
        bubble.style.height = `${r}px`;
        bubble.style.background = `radial-gradient(circle at 30% 20%, rgba(255,255,255,0.20), rgba(0,0,0,0.02) 45%), ${m.color}`;

        const inner = document.createElement('div');
        inner.style.display = 'grid';
        inner.style.placeItems = 'center';
        inner.style.transform = 'translateY(-2px)';

        const name = document.createElement('div');
        name.className = 'name';
        name.textContent = abbreviate(m.name);

        const meta = document.createElement('div');
        meta.className = 'meta';
        meta.textContent = `${m.intelligence} • ${m.speed} tok/s • $${m.price.toFixed(2)}`;

        inner.appendChild(name);
        inner.appendChild(meta);
        bubble.appendChild(inner);
        chart.appendChild(bubble);
      }
    };

    const buildRows = (containerId, items, unit, accent) => {
      const el = document.getElementById(containerId);
      el.innerHTML = '';
      items.forEach(([model, val], i) => {
        const row = document.createElement('div');
        row.className = `row ${accent}`;

        const rank = document.createElement('div');
        rank.className = 'rank';
        rank.textContent = `${i+1}`;

        const name = document.createElement('div');
        name.className = 'model';
        name.textContent = model;

        const value = document.createElement('div');
        value.className = 'value';
        value.textContent = unit === '$' ? `$${val.toFixed(2)}` : `${val}`;

        row.appendChild(rank);
        row.appendChild(name);
        row.appendChild(value);

        // small context lines for top entries
        if (containerId === 'intel' && i === 0) {
          const sub = document.createElement('div');
          sub.className = 'sub';
          sub.textContent = 'Top spot is shared (57).';
          row.appendChild(sub);
        }
        if (containerId === 'speed' && i === 0) {
          const sub = document.createElement('div');
          sub.className = 'sub';
          sub.textContent = 'Fastest model is not the smartest.';
          row.appendChild(sub);
        }
        if (containerId === 'price' && i === 0) {
          const sub = document.createElement('div');
          sub.className = 'sub';
          sub.textContent = 'Cheapest is tied at $0.30 per 1M.';
          row.appendChild(sub);
        }

        el.appendChild(row);
      });
    };

    // Render
    placeBubbles();
    buildRows('intel', data.rankings.intelligence, 'score', 'accentCyan');
    buildRows('speed', data.rankings.speed, 'tok/s', 'accentTeal');
    buildRows('price', data.rankings.price, '$', 'accentAmber');
  </script>
